{
  "implementation": "def solve(case):
    edges = case['edges']
    refinement = case['refinement']
    members = {}
    for v, g in refinement.items():
        members.setdefault(g, []).append(v)
    agg = {}
    for src, dst, w in edges:
        gs = refinement[src]
        gd = refinement[dst]
        key = (gs, gd)
        agg[key] = agg.get(key, 0) + w
    aggregate_edges = [[gs, gd, total] for (gs, gd), total in agg.items()]
    return {"aggregate_edges": aggregate_edges, "members": members}"
}
